/**
 * Draws the two pictures a shared link shows (1200×630): site/assets/og.png for the landing (the lockup, its title in both languages and the
 * statue) and site/preview/assets/og.png for the preview download page (the lockup, the concept line and the hand with the golden apple).
 * Drawn from HTML in headless Chrome, with the web fonts each page uses; nothing is generated by an image model.
 *
 *   node scripts/build-og.mjs [cdp-port]
 */
import {readFileSync, writeFileSync} from 'node:fs';
import {openPage, sleep} from './lib/headless.mjs';

const root = new URL('..', import.meta.url);
const read = p => readFileSync(new URL(p, root));
const lockup = read('site/assets/brand/apple-a-lockup.svg').toString('utf8').replace('<svg ', '<svg class="lockup" ');
const webp = p => 'data:image/webp;base64,' + read(p).toString('base64');
const page = (fonts, style, body) => `<!doctype html><html lang="ko"><head><meta charset="utf-8">
<link href="https://fonts.googleapis.com/css2?${fonts}&display=block" rel="stylesheet">
<style>
*{box-sizing:border-box}html,body{margin:0;width:1200px;height:630px;overflow:hidden;background:#f7f5ef;color:#211f19;font-synthesis-style:none;word-break:keep-all}
.lockup{position:absolute;left:84px;top:68px;height:40px;width:auto}
small{position:absolute;left:86px;bottom:64px;font-family:"Geist Mono";font-size:15px;letter-spacing:.12em;text-transform:uppercase;color:#67645a}
${style}
</style></head><body>${lockup}${body}</body></html>`;

const PICTURES = [
  {out: 'site/assets/og.png', need: ['Fraunces', 'Noto Serif KR 400'], html: page('family=Fraunces:opsz,wght@9..144,400&family=Noto+Serif+KR:wght@400&family=Geist+Mono:wght@400', `
h1{position:absolute;left:82px;top:168px;margin:0;font-family:"Fraunces";font-weight:400;font-variation-settings:"opsz" 144;font-size:96px;line-height:1;letter-spacing:-.035em;color:#292820}
h1 span{display:block}
p{position:absolute;left:86px;top:394px;margin:0;font-family:"Noto Serif KR";font-weight:400;font-size:40px;line-height:1.2;letter-spacing:-.03em;color:#8f6a1c}
img{position:absolute;right:46px;top:44px;width:500px;height:542px;object-fit:contain}`,
    `<h1><span>Shape before</span><span>you build.</span></h1><p>만들기 전에, 방향부터.</p><small>Free · macOS · no account</small><img src="${webp('site/assets/brand/aphrodite.webp')}" alt="">`)},
  {out: 'site/preview/assets/og.png', need: ['Noto Serif KR 900', 'Playfair Display 800 normal', 'Playfair Display 800 italic'], html: page('family=Noto+Serif+KR:wght@900&family=Playfair+Display:ital,wght@0,800;1,800&family=Geist+Mono:wght@400', `
h1{position:absolute;left:84px;top:170px;margin:0;font-family:"Noto Serif KR";font-weight:900;font-size:84px;line-height:1.14;letter-spacing:-.05em}
h1 span{display:block}.gold{color:#a37a22}
p{position:absolute;left:86px;top:392px;margin:0;font-family:"Playfair Display";font-weight:800;font-size:34px;line-height:1.2;letter-spacing:-.01em;color:#5b584e}
p em{font-style:italic;color:#a37a22}
img{position:absolute;right:40px;top:70px;width:470px;height:470px;object-fit:contain}`,
    `<h1><span>쓰던 AI는 그대로,</span><span>작업물은 <span class="gold" style="display:inline">한곳에.</span></span></h1>
<p>Keep your AI. Keep the work in <em>one place.</em></p><small>Free · macOS 13+ · no account</small><img src="${webp('site/assets/brand/apple-hand.webp')}" alt="">`)},
];

const port = Number(process.argv[2] ?? 9413);
for (const [i, {out, need, html}] of PICTURES.entries()) {
  const {evaluate, send, close} = await openPage('data:text/html;charset=utf-8,' + encodeURIComponent(html), {cdp: port + i, profile: '/tmp/aphrodite-og-profile-' + i});
  try {
    await send('Emulation.setDeviceMetricsOverride', {width: 1200, height: 630, deviceScaleFactor: 1, mobile: false});
    await evaluate('document.fonts.ready.then(() => new Promise(r => setTimeout(r, 800))).then(() => true)');
    const faces = await evaluate('[...document.fonts].filter(f => f.status === "loaded").map(f => f.family + " " + f.weight + " " + f.style)');
    for (const n of need) if (!faces.some(f => f.startsWith(n))) throw new Error(out + ': the web font did not arrive: ' + n + ' (got ' + faces.join(', ') + ')');
    await sleep(200);
    const {result} = await send('Page.captureScreenshot', {format: 'png', clip: {x: 0, y: 0, width: 1200, height: 630, scale: 1}});
    writeFileSync(new URL(out, root), Buffer.from(result.data, 'base64'));
    console.log(out, [...new Set(faces)].join(', '));
  } finally { close(); }
}
